import React, { ReactNode } from 'react';

// Base props that all variants share
interface BaseAlertProps {
  children: ReactNode;
  onClose?: () => void;
}

// Discriminated union: type determines which props are available
type AlertProps = 
  | (BaseAlertProps & { type: 'info'; title?: string })
  | (BaseAlertProps & { type: 'error'; errorCode: string; title: string })
  | (BaseAlertProps & { type: 'success'; autoDismiss?: boolean });

const Alert: React.FC<AlertProps> = (props) => {
  const { type, children, onClose } = props;

  return (
    <div className={`alert alert--${type}`} role="alert">
      {type === 'error' && <span className="error-code">{props.errorCode}</span>}
      {props.title && <h4>{props.title}</h4>}
      <div>{children}</div>
      {onClose && <button onClick={onClose}>×</button>}
    </div>
  );
};

