import { useReducer } from 'react';

// Define the state shape
interface FormState {
  values: { username: string; email: string; password: string };
  errors: { username?: string; email?: string; password?: string };
  isSubmitting: boolean;
  isValid: boolean;
}

// Define all possible actions
type FormAction =
  | { type: 'SET_FIELD'; field: string; value: string }
  | { type: 'SET_ERROR'; field: string; error: string }
  | { type: 'CLEAR_ERROR'; field: string }
  | { type: 'SUBMIT_START' }
  | { type: 'SUBMIT_SUCCESS' }
  | { type: 'SUBMIT_FAILURE'; errors: Record<string, string> };

const initialState: FormState = {
  values: { username: '', email: '', password: '' },
  errors: {},
  isSubmitting: false,
  isValid: false
};

function formReducer(state: FormState, action: FormAction): FormState {
  switch (action.type) {
    case 'SET_FIELD':
      return {
        ...state,
        values: { ...state.values, [action.field]: action.value },
        isValid: Object.keys(state.errors).length === 0
      };
    case 'SET_ERROR':
      return {
        ...state,
        errors: { ...state.errors, [action.field]: action.error },
        isValid: false
      };
    case 'CLEAR_ERROR': {
      const { [action.field]: _, ...restErrors } = state.errors;
      return { ...state, errors: restErrors };
    }
    case 'SUBMIT_START':
      return { ...state, isSubmitting: true };
    case 'SUBMIT_SUCCESS':
      return { ...initialState };
    case 'SUBMIT_FAILURE':
      return { ...state, isSubmitting: false, errors: action.errors };
    default:
      return state;
  }
}

function RegistrationForm(): JSX.Element {
  const [state, dispatch] = useReducer(formReducer, initialState);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    const { name, value } = e.target;
    dispatch({ type: 'SET_FIELD', field: name, value });

    // Simple validation
    if (name === 'email' && !value.includes('@')) {
      dispatch({ type: 'SET_ERROR', field: name, error: 'Invalid email' });
    } else {
      dispatch({ type: 'CLEAR_ERROR', field: name });
    }
  };

  const handleSubmit = async (e: React.FormEvent): Promise<void> => {
    e.preventDefault();
    dispatch({ type: 'SUBMIT_START' });

    try {
      await fetch('/api/register', {
        method: 'POST',
        body: JSON.stringify(state.values)
      });
      dispatch({ type: 'SUBMIT_SUCCESS' });
    } catch {
      dispatch({ type: 'SUBMIT_FAILURE', errors: { general: 'Server error' } });
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name="username" value={state.values.username} onChange={handleChange} />
      {state.errors.username && <span>{state.errors.username}</span>}

      <input name="email" value={state.values.email} onChange={handleChange} />
      {state.errors.email && <span>{state.errors.email}</span>}

      <input name="password" type="password" value={state.values.password} onChange={handleChange} />

      <button disabled={state.isSubmitting || !state.isValid}>
        {state.isSubmitting ? 'Submitting...' : 'Register'}
      </button>
    </form>
  );
}

